// Machine A sends a payment-processing request to Machine B (a
// payment provider), then experiences a genuine timeout - no
// response arrives within the expected window.

// WITHOUT idempotency (genuinely dangerous):
async function chargeCustomer_noIdempotency(amount: number, cardToken: string) {
  try {
    return await paymentProvider.charge({ amount, cardToken });
  } catch (timeoutErr) {
    // A cannot know whether B genuinely processed this charge or not
    // - naively retrying here risks a GENUINE double charge, if B's
    // original response (not the original request) was what was lost
    return await paymentProvider.charge({ amount, cardToken }); // DANGEROUS
  }
}

// WITH idempotency (Module 28 lesson 3's exact, correct discipline,
// now understood as the genuine, correct RESPONSE to this lesson's
// foundational ambiguity, not merely a defensive habit):
async function chargeCustomer_withIdempotency(amount: number, cardToken: string, orderId: string) {
  try {
    return await paymentProvider.charge({ amount, cardToken, idempotencyKey: orderId });
  } catch (timeoutErr) {
    // SAFE to retry with the SAME idempotencyKey - if B genuinely
    // already processed this exact charge (the lost-response
    // scenario), the payment provider's own deduplication correctly
    // returns the ORIGINAL result rather than genuinely charging again
    return await paymentProvider.charge({ amount, cardToken, idempotencyKey: orderId });
  }
}

