// TRACE:

// SCENARIO A: the original reserve() request never reached Service
// B at all (lost in transit) - B never processed anything, and the
// naive retry is genuinely, completely safe in this specific case.

// SCENARIO B: the original request DID reach B, and B genuinely
// reserved the inventory successfully, but B's RESPONSE confirming
// this was lost on its way back to A - in this case, the naive
// retry would cause B to reserve the SAME inventory a SECOND time,
// genuinely over-reserving stock that should only have been
// reserved once.

// RISK: Service A cannot distinguish between scenario A and
// scenario B from its own vantage point - the naive retry is unsafe
// specifically because of scenario B's genuine possibility.

// CORRECTED, IDEMPOTENT VERSION:
async function reserveInventory_fixed(orderId: string, items: Item[]) {
  try {
    return await inventoryService.reserve({ items, idempotencyKey: orderId });
  } catch (timeoutErr) {
    // Safe to retry with the SAME idempotencyKey - if scenario B
    // genuinely occurred, the inventory service's own deduplication
    // correctly returns the original reservation rather than
    // reserving the same inventory again
    return await inventoryService.reserve({ items, idempotencyKey: orderId });
  }
}

