Since lesson 1 established no two machines' wall clocks are ever
genuinely, perfectly synchronized, ordering events CORRECTLY across
machines requires a LOGICAL clock instead - a simple counter, NOT a
real, wall-clock time, that captures genuine causal order:

class LamportClock {
  private counter = 0;

  // Called whenever this machine performs any LOCAL event
  tick(): number {
    this.counter++;
    return this.counter;
  }

  // Called whenever this machine RECEIVES a message from another
  // machine, carrying that OTHER machine's own logical timestamp
  receive(remoteTimestamp: number): number {
    this.counter = Math.max(this.counter, remoteTimestamp) + 1;
    return this.counter;
  }
}

// Machine A's clock: starts at 0
const clockA = new LamportClock();
const eventA1 = clockA.tick(); // 1 - A's first local event

// A sends a message to B, attaching its own logical timestamp (1)

// Machine B's clock: starts independently at 0
const clockB = new LamportClock();
const eventB1 = clockB.tick(); // 1 - B's own, GENUINELY UNRELATED
                                  // first local event
const eventB2 = clockB.receive(eventA1); // 2 - upon receiving A's
  // message (timestamp 1), B's clock jumps to max(1, 1) + 1 = 2,
  // correctly capturing that this event happened genuinely AFTER
  // the message that caused it, regardless of either machine's
  // own actual wall-clock time

