// CATEGORY 1 - a user's current account balance, used to authorize
// a withdrawal: STRONG consistency required
async function getBalanceForWithdrawal(userId: string): Promise<number> {
  // Read directly from the PRIMARY, authoritative node, never a
  // replica that might be lagging behind - genuinely necessary here,
  // since acting on stale data risks a real overdraft
  return await primaryDatabase.getBalance(userId);
}

// CATEGORY 2 - a social media post's 'like' count, displayed on the
// post itself: EVENTUAL consistency is genuinely acceptable
async function getLikeCount(postId: string): Promise<number> {
  // Read from ANY available replica, even if it's a few seconds
  // behind the absolute latest count - the genuine cost of brief
  // staleness here is essentially zero
  return await anyReplica.getLikeCount(postId);
}

// CATEGORY 3 - a comment thread, where replies must always appear
// AFTER the comment they're replying to: CAUSAL consistency required
async function getCommentThread(postId: string): Promise<Comment[]> {
  const comments = await anyReplica.getComments(postId);
  // Sorting by each comment's own LOGICAL timestamp (lesson 3's
  // Lamport clock), NOT by wall-clock time, correctly preserves the
  // genuine causal relationship between an original comment and its
  // replies, even if different replicas received them in a slightly
  // different real-time order
  return comments.sort((a, b) => a.logicalTimestamp - b.logicalTimestamp);
}

