// eventual consistency's lower latency and higher availability
// genuinely matter more than perfect, real-time accuracy.

// C (collaborative document edit history): CAUSAL CONSISTENCY.
// Reasoning: edits that build on previous edits must always be seen
// in their correct causal order, even though edits to genuinely
// unrelated parts of the document could be seen in different orders
// by different collaborators without any real problem.

interface Event {
  machineId: string;
  logicalTimestamp: number;
  description: string;
}

function sortEventsByLogicalOrder(events: Event[]): Event[] {
  return [...events].sort((a, b) => a.logicalTimestamp - b.logicalTimestamp);
}

