A NAIVE approach - simple modulo hashing - distributes keys evenly,
but catastrophically reshuffles EVERY key when the number of nodes
changes at all:

function naiveNodeSelection(key: string, nodeCount: number): number {
  const hash = simpleHash(key);
  return hash % nodeCount; // changing nodeCount from 3 to 4 changes
                              // the result for ALMOST EVERY key,
                              // causing a massive, unnecessary cache
                              // invalidation across the entire system
}

CONSISTENT HASHING - maps both NODES and KEYS onto the same
conceptual 'ring', with a key belonging to the NEXT node clockwise
from its own position - adding or removing one node only affects
keys near that SPECIFIC node's position on the ring, not every key:

class ConsistentHashRing {
  private ring: Map<number, string> = new Map();

  addNode(nodeId: string) {
    const position = simpleHash(nodeId);
    this.ring.set(position, nodeId);
  }

  getNodeForKey(key: string): string {
    const keyPosition = simpleHash(key);
    const sortedPositions = [...this.ring.keys()].sort((a, b) => a - b);
    // find the first node position >= the key's position (wrapping
    // around the ring back to the start if genuinely necessary)
    const nodePosition = sortedPositions.find((p) => p >= keyPosition) ?? sortedPositions[0];
    return this.ring.get(nodePosition)!;
  }
}

