// NAIVE MODULO APPROACH - adding a 4th node to an existing 3-node setup

// BEFORE (3 nodes): key 'user:123' -> hash % 3 -> node 1
// BEFORE (3 nodes): key 'user:456' -> hash % 3 -> node 2
// BEFORE (3 nodes): key 'user:789' -> hash % 3 -> node 0

// AFTER adding a 4th node: hash % 4 instead of hash % 3
// 'user:123' -> hash % 4 -> COULD BE ANY DIFFERENT NODE
// 'user:456' -> hash % 4 -> COULD BE ANY DIFFERENT NODE
// 'user:789' -> hash % 4 -> COULD BE ANY DIFFERENT NODE
// RESULT: potentially EVERY single key in the entire cache now maps
// to a DIFFERENT node than before, causing a near-total cache miss
// storm across the whole system the moment this 4th node is added

// CONSISTENT HASHING APPROACH - adding the same 4th node
const ring = new ConsistentHashRing();
ring.addNode('node-0');
ring.addNode('node-1');
ring.addNode('node-2');

// Most keys' node assignments, established before the 4th node existed
const before = ring.getNodeForKey('user:123'); // e.g., 'node-1'

ring.addNode('node-3'); // adding the new node

const after = ring.getNodeForKey('user:123');
