function simpleHash(input: string): number {
  let hash = 0;
  for (let i = 0; i < input.length; i++) {
    hash = (hash * 31 + input.charCodeAt(i)) % 1000000;
  }
  return hash;
}

class ConsistentHashRing {
  private ring: Map<number, string> = new Map();

  addNode(nodeId: string) {
    this.ring.set(simpleHash(nodeId), nodeId);
  }

  removeNode(nodeId: string) {
    const position = simpleHash(nodeId);
    this.ring.delete(position);
  }

  getNodeForKey(key: string): string {
    const keyPosition = simpleHash(key);
    const sortedPositions = [...this.ring.keys()].sort((a, b) => a - b);
    const nodePosition = sortedPositions.find((p) => p >= keyPosition) ?? sortedPositions[0];
    return this.ring.get(nodePosition)!;
  }
}

// VERIFICATION TEST
const ring = new ConsistentHashRing();
ring.addNode('node-0');
ring.addNode('node-1');
ring.addNode('node-2');

const sampleKeys = Array.from({ length: 20 }, (_, i) => `user:${i}`);
const before = sampleKeys.map((k) => ring.getNodeForKey(k));

ring.addNode('node-3');

const after = sampleKeys.map((k) => ring.getNodeForKey(k));

const unchangedCount = before.filter((node, i) => node === after[i]).length;
console.log(`${unchangedCount}/20 keys kept their original node assignment`);
// Expect MOST keys (not all, but a clear majority) to remain unchanged,
// confirming consistent hashing's disruption-limiting property

