Publishing an event to a SPECIFIC partition, deterministically chosen
by a relevant key (directly extending lesson 3's causal-consistency
need - events for the SAME entity should land in the SAME partition,
preserving their correct relative order):

function selectPartition(orderId: string, partitionCount: number): number {
  const hash = simpleHash(orderId);
  return hash % partitionCount; // ALL events for this SAME orderId
                                    // consistently land in the SAME
                                    // partition, preserving their
                                    // genuine, correct relative order
}

async function publishOrderEvent(orderId: string, eventType: string, data: object) {
  const partition = selectPartition(orderId, TOTAL_PARTITIONS);
  await eventBroker.publish(`order-events-partition-${partition}`, { eventType, orderId, data });
}

// A CONSUMER GROUP - multiple worker instances, each assigned a
// distinct, non-overlapping SUBSET of partitions, working in parallel
const consumerGroup = new ConsumerGroup('inventory-service', {
  topic: 'order-events',
  totalPartitions: TOTAL_PARTITIONS,
  instanceId: process.env.INSTANCE_ID, // e.g., 'worker-0', 'worker-1'
  totalInstances: process.env.TOTAL_WORKERS
});

consumerGroup.onMessage(async (message, partition) => {
  // this worker ONLY receives messages from its OWN assigned
  // partitions, never from partitions another worker owns
  await processInventoryUpdate(message);
});

